<template><div class="section"><div class="section-header"><h2 class="section-title">{{ editing ? '编辑接入模板' : '新建接入模板' }}</h2><el-button @click="router.push('/vendor-templates')">返回</el-button></div><div class="section-body"><el-form ref="formRef" :model="form" label-position="top"><div class="grid"><el-form-item label="模板名称" required><el-input v-model="form.name" /></el-form-item><el-form-item label="供应商名称" required><el-input v-model="form.supplier_name" /></el-form-item><el-form-item label="协议"><el-select v-model="form.api_protocol" class="full"><el-option label="OpenAI-compatible" value="openai"/><el-option label="Anthropic" value="anthropic"/><el-option label="Gemini" value="gemini"/></el-select></el-form-item><el-form-item label="模型" required><el-input v-model="form.model" /></el-form-item><el-form-item label="供应商 API URL" required><el-input v-model="form.base_url" placeholder="https://provider.example.com" /></el-form-item><el-form-item label="供应商 Endpoint"><el-input v-model="form.endpoint" /></el-form-item><el-form-item label="官方参考 API URL" required><el-input v-model="form.reference_base_url" /></el-form-item><el-form-item label="官方参考 Endpoint"><el-input v-model="form.reference_endpoint" /></el-form-item><el-form-item label="官方参考模型" required><el-input v-model="form.reference_model" /></el-form-item><el-form-item label="输入 Token 测试组"><el-input v-model="lengths" placeholder="128,1024,4096" /></el-form-item><el-form-item label="最大输出 Token"><el-input-number v-model="form.max_output_tokens" :min="1" :max="65536" class="full" /></el-form-item><el-form-item label="价格规则"><el-select v-model="form.pricing_rule_id" class="full"><el-option v-for="rule in rules" :key="rule.id" :label="`${rule.id} · ${rule.verified ? '已验证' : '未验证'}`" :value="rule.id" /></el-select></el-form-item><el-form-item label="输入 Token 绝对容差"><el-input-number v-model="form.token_abs_tolerance" :min="0" :max="10000" class="full" /></el-form-item></div><el-alert v-if="selectedRule && !selectedRule.verified" title="当前价格规则未验证官方来源，只能用于试算，不能证明官方报价。" type="warning" :closable="false"/><div class="actions"><el-button type="primary" :loading="saving" @click="save">保存模板</el-button></div></el-form></div></div></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { createVendorTemplate, getVendorBillingConfig, getVendorTemplate, updateVendorTemplate } from '../api/client'
const route=useRoute(); const router=useRouter(); const formRef=ref(); const saving=ref(false); const rules=ref([]); const lengths=ref('128,1024,4096'); const editing=computed(()=>Boolean(route.params.id)); const selectedRule=computed(()=>rules.value.find(r=>r.id===form.pricing_rule_id)); const form=reactive({name:'供应商接入模板',supplier_name:'',api_protocol:'openai',base_url:'',endpoint:'/v1/chat/completions',model:'',reference_base_url:'https://api.openai.com',reference_endpoint:'/v1/chat/completions',reference_model:'gpt-4o-mini',input_token_lengths:[128,1024,4096],max_output_tokens:128,temperature:0,timeout_sec:120,connect_timeout_sec:30,enable_stream:false,cache_test_enabled:false,pricing_rule_id:'',token_abs_tolerance:16,token_relative_tolerance:.05,anthropic_version:'2023-06-01',reference_anthropic_version:'2023-06-01'})
async function save(){const vals=lengths.value.split(',').map(v=>Number(v.trim())); if(!form.name||!form.supplier_name||!form.base_url||!form.model||!form.reference_base_url||!form.reference_model||vals.some(v=>!Number.isInteger(v)||v<=0)||!form.pricing_rule_id){ElMessage.error('请完整填写模板必填项和合法 Token 测试组');return} saving.value=true; try {const payload={...form,input_token_lengths:vals}; if(editing.value) await updateVendorTemplate(route.params.id,payload); else await createVendorTemplate(payload); ElMessage.success('模板已保存'); router.push('/vendor-templates')} catch(e){ElMessage.error(e.message)} finally{saving.value=false}}
onMounted(async()=>{try{rules.value=(await getVendorBillingConfig()).pricing_rules||[]; if(!form.pricing_rule_id&&rules.value.length) form.pricing_rule_id=rules.value[0].id; if(editing.value){const data=await getVendorTemplate(route.params.id); Object.assign(form,data.config||{}); lengths.value=(form.input_token_lengths||[]).join(',')}}catch(e){ElMessage.error(e.message)}})
</script><style scoped>.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.full{width:100%}.actions{margin-top:18px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style>
